import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Dyi9RH6t.js";var i=JSON.parse('{"title":"Overview","description":"Enable WarpDrive\'s regionalized debug logging with `setWarpDriveLogging` at runtime or via build config, using flags such as LOG_REQUESTS, LOG_CACHE, and LOG_GRAPH.","frontmatter":{"title":"Overview","description":"Enable WarpDrive\'s regionalized debug logging with `setWarpDriveLogging` at runtime or via build config, using flags such as LOG_REQUESTS, LOG_CACHE, and LOG_GRAPH."},"headers":[],"relativePath":"guides/the-manual/debugging/index.md","filePath":"guides/the-manual/debugging/index.md"}'),a={name:`guides/the-manual/debugging/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="debugging" tabindex="-1">Debugging <a class="header-anchor" href="#debugging" aria-label="Permalink to “Debugging”">​</a></h1><p>WarpDrive ships with comprehensive instrumented logging throughout its internals. All instrumentation is <strong>stripped from production builds</strong> — enabling it has zero production cost.</p><p>Logging is regionalized by concern so you can enable only the areas relevant to your investigation.</p><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick Start”">​</a></h2><p>Open your browser&#39;s DevTools console and call:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setWarpDriveLogging</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ LOG_REQUESTS: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, LOG_CACHE: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>No import needed — the helper is attached to <code>globalThis</code> automatically.</p><h2 id="runtime-activation" tabindex="-1">Runtime Activation <a class="header-anchor" href="#runtime-activation" aria-label="Permalink to “Runtime Activation”">​</a></h2><div class="tip custom-block"><p class="custom-block-title">💡 Works directly in browser DevTools</p><p>No import required. Config is preserved across page reloads via <code>sessionStorage</code>.</p></div><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setWarpDriveLogging</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  LOG_REQUESTS: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  LOG_CACHE: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  LOG_NOTIFICATIONS: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>Settings persist for the current browser tab only. Open a new tab (or call the helper with the flag set to <code>false</code>) to reset.</p><h2 id="build-time-activation" tabindex="-1">Build-time Activation <a class="header-anchor" href="#build-time-activation" aria-label="Permalink to “Build-time Activation”">​</a></h2><p>To enable logging by default in a dev environment, use the build config:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(__dirname, app, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  debug: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LOG_REQUESTS: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LOG_CACHE: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>All flags default to <code>false</code>. Runtime activation via <code>setWarpDriveLogging</code> overrides build-time values for the current tab.</p><h2 id="log-flags" tabindex="-1">Log Flags <a class="header-anchor" href="#log-flags" aria-label="Permalink to “Log Flags”">​</a></h2><h3 id="requests" tabindex="-1">Requests <a class="header-anchor" href="#requests" aria-label="Permalink to “Requests”">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>What it logs</th></tr></thead><tbody><tr><td><code>LOG_REQUESTS</code></td><td>All requests issued by the RequestManager</td></tr><tr><td><code>LOG_REQUEST_STATUS</code></td><td>Status updates for in-flight network requests</td></tr></tbody></table><h3 id="cache" tabindex="-1">Cache <a class="header-anchor" href="#cache" aria-label="Permalink to “Cache”">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>What it logs</th></tr></thead><tbody><tr><td><code>LOG_CACHE</code></td><td>All cache updates — both local and remote state</td></tr><tr><td><code>LOG_CACHE_POLICY</code></td><td>Decisions made by the cache policy (e.g. whether to refetch)</td></tr><tr><td><code>LOG_NOTIFICATIONS</code></td><td>Notifications received by the NotificationManager</td></tr></tbody></table><h3 id="relationships" tabindex="-1">Relationships <a class="header-anchor" href="#relationships" aria-label="Permalink to “Relationships”">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>What it logs</th></tr></thead><tbody><tr><td><code>LOG_GRAPH</code></td><td>Updates to the relationship graph (pointer storage)</td></tr><tr><td><code>DEBUG_RELATIONSHIP_NOTIFICATIONS</code></td><td>Cause of change notifications when processing <code>hasMany</code> updates</td></tr></tbody></table><h3 id="records-identity" tabindex="-1">Records &amp; Identity <a class="header-anchor" href="#records-identity" aria-label="Permalink to “Records &amp; Identity”">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>What it logs</th></tr></thead><tbody><tr><td><code>LOG_IDENTIFIERS</code></td><td>Peek, generation, and updates to Record Identifiers</td></tr><tr><td><code>LOG_INSTANCE_CACHE</code></td><td>Creation and removal of RecordData and Record instances</td></tr></tbody></table><h3 id="reactivity" tabindex="-1">Reactivity <a class="header-anchor" href="#reactivity" aria-label="Permalink to “Reactivity”">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>What it logs</th></tr></thead><tbody><tr><td><code>LOG_REACT_SIGNAL_INTEGRATION</code></td><td>React-specific reactivity events</td></tr></tbody></table><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to “Performance”">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>What it logs</th></tr></thead><tbody><tr><td><code>LOG_METRIC_COUNTS</code></td><td>Key count metrics useful for performance profiling</td></tr></tbody></table><h2 id="deprecated-flags" tabindex="-1">Deprecated Flags <a class="header-anchor" href="#deprecated-flags" aria-label="Permalink to “Deprecated Flags”">​</a></h2><p>These flags were removed in v5.5. They have no effect — use <code>LOG_CACHE</code> instead.</p><table tabindex="0"><thead><tr><th>Removed flag</th><th>Replacement</th></tr></thead><tbody><tr><td><code>LOG_MUTATIONS</code></td><td><code>LOG_CACHE</code></td></tr><tr><td><code>LOG_OPERATIONS</code></td><td><code>LOG_CACHE</code></td></tr><tr><td><code>LOG_PAYLOADS</code></td><td><code>LOG_CACHE</code></td></tr></tbody></table><h2 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to “API Reference”">​</a></h2><p>See <a href="/pr-preview/pr-11292/api/@warp-drive/core/build-config/debugging/"><code>@warp-drive/core/build-config/debugging</code></a> for the full API reference.</p>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};